// Typed bridge over the generated Tauri bindings: thin command wrappers and
// the "player" event subscription. UI code should import from here, not from
// bindings.ts directly (bindings is regenerated by specta).
import { listen, type UnlistenFn } from "@tauri-apps/api/event";
import {
	commands,
	type Command,
	type Event,
	type TrackView,
} from "./bindings";

/** Open a folder: scan + start playing. Resolves the library views, or null
 *  when the user cancels the dialog (the backend's "no folder selected"
 *  sentinel — see `open_folder` in `commands.rs`). Any other backend error
 *  (scan failure, empty folder, …) still throws so the UI can surface it. */
export async function openFolder(): Promise<TrackView[] | null> {
	const r = await commands.openFolder();
	if (r.status === "error") {
		if (r.error === "no folder selected") return null;
		throw new Error(r.error);
	}
	return r.data;
}

/** Current library views (renders without re-scanning). */
export function libraryViews(): Promise<TrackView[]> {
	return commands.libraryViews();
}

/** Fire one transport/queue command at the actor (fire-and-forget). */
export async function sendCommand(cmd: Command): Promise<void> {
	const r = await commands.sendCommand(cmd);
	if (r.status === "error") {
		throw new Error(r.error);
	}
}

/** Cover art for a track id as a `data:` URL, or null when the track has none /
 *  a read error occurs (art is optional decoration — never worth surfacing as
 *  an error). Resolves embedded art and an external cover file (e.g. Scans/). */
export async function trackArt(id: number): Promise<string | null> {
	const r = await commands.trackArt(id);
	return r.status === "error" ? null : r.data;
}

/** Subscribe to the actor's "player" event channel (throttled Tick ~8 Hz +
 *  Queue on mutation). Returns the unsubscribe fn. */
export function onPlayerEvent(
	handler: (event: Event) => void,
): Promise<UnlistenFn> {
	return listen<Event>("player", (e) => handler(e.payload));
}
